import { randomUUID } from 'node:crypto'
import type { Context } from '@deepseek-ai/cordis'
import { installModelSelection, type ModelSelectionRef } from '@deepseek-ai/dsh-agent'
import type {} from '@deepseek-ai/dsh-agent-default-model'
import { SessionId, type SessionHeader } from '@deepseek-ai/dsh-session'
import type {} from '@deepseek-ai/dsh-session-persistence'
import type { SkillSummary } from '@deepseek-ai/dsh-skill'
import type { ApprovalRequest } from '@deepseek-ai/dsh-user-approval'
import type {} from '@deepseek-ai/dsh-user-questions'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type {} from '@deepseek-ai/dsh-cmdline'
import { render, type Instance } from 'ink'
import React from 'react'
import { App } from './app.js'
import { TuiController } from './controller.js'
import { HerdrBridge } from './herdr.js'
import { resolveTheme } from './theme.js'
import { detectDshVersion, dshUpgradeCommand, isVersionNewer, latestDshVersion } from './version.js'

export const name = 'dsh-tui'
export const inject = [
  'agentDefaultModel',
  'agents',
  'sessions',
  'sessionPersistence',
  'userQuestions',
]

export interface Config {
  continueSession?: boolean
  resumeSessionId?: string
  initialPrompt?: string
}

function newestSessionForCwd(headers: readonly SessionHeader[], cwd: string): SessionHeader | undefined {
  let newest: SessionHeader | undefined
  for (const header of headers) {
    if (header.cwd !== cwd || header.origin === 'subagent') continue
    if (newest === undefined || header.createdAt > newest.createdAt) newest = header
  }
  return newest
}

async function run(ctx: Context, config: Config): Promise<void> {
  if (!process.stdin.isTTY || !process.stdout.isTTY) {
    throw new Error('dsh-tui needs an interactive terminal; use the headless profile for scripts')
  }
  const theme = await resolveTheme()
  await ctx.get('loader')?.await()
  const agents = ctx.get('agents')
  const defaultModel = ctx.get('agentDefaultModel')
  const sessions = ctx.get('sessions')
  const persistence = ctx.get('sessionPersistence')
  const userQuestions = ctx.get('userQuestions')
  const skills = ctx.get('skills')
  const llm = ctx.get('llm')
  const appExit = ctx.get('appExit')
  if (agents === undefined || defaultModel === undefined || sessions === undefined
      || persistence === undefined || userQuestions === undefined || appExit === undefined) return

  let ink: Instance | undefined
  let handle: Awaited<ReturnType<typeof agents.create>> | undefined
  const herdr = new HerdrBridge()
  const permissionPresets = ctx.get('permissionPresets')
  const commands = ctx.get('commands')
  const controller = new TuiController(async () => {
    if (handle !== undefined) {
      if (handle.agent.status === 'running') handle.agent.cancel({ kind: 'user' })
      await handle.agent.whenIdle()
      await sessions.flush(handle.agent.session)
    }
    ink?.unmount()
    await herdr.dispose()
    appExit(0)
  }, {
    ...(permissionPresets === undefined ? {} : { permissionPresets: { names: permissionPresets.names } }),
    ...(commands === undefined ? {} : {
      commands: {
        execute: (agent, line, signal) => commands.execute(agent, line, signal),
      },
    }),
    ...(skills === undefined ? {} : {
      skills: {
        list: async (signal) => {
          if (handle === undefined) return []
          const summaries: SkillSummary[] = await skills.list({
            cwd: process.cwd(),
            signal,
            scope: handle.agent,
          })
          return summaries
            .filter(skill => skill.invocation.userInvocable)
            .map(skill => ({ name: skill.name, description: skill.description }))
        },
      },
    }),
  })
  controller.setTheme(theme)
  const dshVersion = detectDshVersion()
  controller.setDshVersion(dshVersion)
  const disposeHerdr = controller.subscribe(() => { void herdr.sync(controller.snapshot()) })
  void herdr.sync(controller.snapshot())
  ctx.effect(() => async () => {
    disposeHerdr()
    await herdr.dispose()
  })

  const disposeQuestions = userQuestions.registerProvider({
    ask: request => controller.askQuestions(request),
  })
  const disposeApproval = ctx.on('approval/request', (request: ApprovalRequest, next) => {
    if (handle === undefined || request.agent !== handle.agent) return next()
    return controller.requestApproval(request)
  }, { prepend: true })

  const selection = defaultModel.currentSelection()
  const setup = (agentCtx: Context): void => {
    const selected: ModelSelectionRef = { current: selection, assembled: undefined }
    installModelSelection(agentCtx, selected)
  }

  let resumeId = config.resumeSessionId
  if (resumeId === undefined && config.continueSession === true) {
    const previous = newestSessionForCwd(await persistence.list(), process.cwd())
    resumeId = previous?.id
  }

  handle = resumeId === undefined
    ? await agents.create({
        sessionId: SessionId(`session-${randomUUID()}`),
        meta: { cwd: process.cwd() },
        agentOptions: { provider: selection.provider, model: selection.model },
        setup,
      })
    : await agents.resume({
        resumeSessionId: SessionId(resumeId),
        agentOptions: { provider: selection.provider, model: selection.model },
        setup,
      })

  await handle.agent.whenIdle()
  controller.loadHistory(handle.agent.session.events)
  controller.bindAgent(handle.agent)
  try {
    const modelInfo = await llm?.resolveModelInfo(selection.provider, selection.model)
    controller.setContextWindow(modelInfo?.context?.contextWindow)
  } catch {
    // Model metadata is optional; usage remains useful without a known context window.
  }

  const disposeStatus = handle.agent.ctx.on('agent/status', ({ agent, status }) => {
    if (agent === handle?.agent) controller.setStatus(status)
  })
  const disposeEvents = handle.agent.ctx.on('session/event', (session, event) => {
    if (session === handle?.agent.session) controller.ingest(event)
  })

  ink = render(React.createElement(App, { controller }), { exitOnCtrlC: false })
  if (dshVersion !== undefined && process.env.DSH_TUI_UPDATE_CHECK !== '0') {
    void latestDshVersion().then((latestVersion) => {
      if (latestVersion !== undefined && isVersionNewer(latestVersion, dshVersion)) {
        controller.setDshUpgrade({
          version: latestVersion,
          command: dshUpgradeCommand(latestVersion),
        })
      }
    })
  }
  if (config.initialPrompt !== undefined) controller.submit(config.initialPrompt)

  ctx.effect(() => async () => {
    disposeEvents()
    disposeStatus()
    disposeApproval()
    disposeQuestions()
    ink?.unmount()
    if (handle !== undefined) await handle.dispose()
  })
}

export function apply(ctx: Context, config: Config): void {
  const appExit = ctx.get('appExit')
  void run(ctx, config).catch((error: unknown) => {
    process.stderr.write(`dsh-tui: ${error instanceof Error ? error.message : String(error)}\n`)
    appExit?.(1)
  })
}
